{
  "name": "@rolldown/test-dev-server",
  "version": "0.0.0",
  "description": "A implementation of a dev server for demonstrating",
  "type": "module",
  "private": true,
  "bin": {
    "serve": "./bin/cli.js"
  },
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    }
  },
  "scripts": {
    "build": "tsc -b",
    "dev": "tsc -b --watch",
    "test": "pnpm run --filter @rolldown/test-dev-server-tests test"
  },
  "dependencies": {
    "@types/ws": "^8.18.0",
    "chokidar": "^4.0.3",
    "connect": "^3.7.0",
    "rolldown": "workspace:*",
    "serve-static": "^2.0.0",
    "ws": "^8.18.1"
  },
  "devDependencies": {
    "@types/connect": "^3.4.38",
    "@types/serve-static": "^1.15.7"
  }
}

[package]
name = "rolldown_testing"
version = "0.1.0"
publish = false

# See more keys and their definitions at https://doc.rust-lang.org/cargo/reference/manifest.html
edition.workspace = true
homepage.workspace = true
license.workspace = true
repository.workspace = true

[lib]
doctest = false
test = false

[lints]
workspace = true

[dependencies]
anyhow = { workspace = true }
dunce = { workspace = true }
glob = { workspace = true }
insta = { workspace = true }
json-strip-comments = { workspace = true }
jsonschema = { workspace = true }
regex = { workspace = true }
rolldown = { workspace = true }
rolldown_common = { workspace = true }
rolldown_error = { workspace = true }
rolldown_sourcemap = { workspace = true }
rolldown_testing_config = { workspace = true }
rolldown_workspace = { workspace = true }
rustc-hash = { workspace = true }
serde_json = { workspace = true }
sugar_path = { workspace = true }
tokio = { workspace = true, features = ["rt", "macros", "sync", "rt-multi-thread"] }
urlencoding = { workspace = true }

[build-dependencies]
rolldown_testing_config = { workspace = true }
schemars = { workspace = true }
serde_json = { workspace = true }

[[bin]]
doctest = false
name = "run-fixture"
path = "./bin/run_fixture.rs"
test = false

{
  "name": "@rolldown/test-dev-server-tests",
  "private": true,
  "license": "MIT",
  "scripts": {
    "test": "vitest run"
  },
  "dependencies": {
    "@rolldown/test-dev-server": "workspace:*",
    "@types/kill-port": "^2.0.3",
    "execa": "^9.2.0",
    "kill-port": "^2.0.1",
    "rimraf": "^6.0.1",
    "vitest": "^3.0.1",
    "fast-glob": "catalog:"
  }
}

{
  "name": "rolldown-tests",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "test:main": "RUST_BACKTRACE=1 ROLLDOWN_TEST=1 vitest run --exclude '**/watch.test.ts' --reporter verbose --hideSkippedTests",
    "test:watcher": "RUST_BACKTRACE=1 ROLLDOWN_TEST=1 vitest run watch.test.ts --reporter verbose --hideSkippedTests",
    "test:stability": "node ./stability/issue-3453/src/build.mjs && node ./stability/issue-3453/verify.mjs",
    "test:types": "vitest run --typecheck.only --reporter verbose --hideSkippedTests",
    "type-check": "tsc --noEmit"
  },
  "dependencies": {
    "rolldown": "workspace:*",
    "vite": "^7.0.0",
    "vitest": "^3.0.1"
  },
  "devDependencies": {
    "@rolldown/test-side-effects-field": "link:./package-fixtures/test-side-effects-field",
    "@rolldown/test-side-effects-field-glob": "file:./package-fixtures/test-side-effects-field-glob",
    "@types/node": "24.4.0",
    "tsx": "^4.19.4"
  },
  "exports": {
    ".": {
      "import": "./src/index.ts"
    },
    "./utils": {
      "import": "./src/utils.ts"
    },
    "./types": {
      "types": "./src/types.ts"
    }
  }
}

{
  "name": "@rolldown/test-side-effects-field",
  "type": "module",
  "main": "index.js",
  "sideEffects": false
}

{
  "name": "@rolldown/test-side-effects-field-glob",
  "type": "module",
  "main": "index.js",
  "sideEffects": ["foo/foo.js"]
}
